#define main learner_main
#include "main.cpp"
#undef main
#include <sstream>
#include <string>

struct Streams
{
    std::istringstream input;
    std::ostringstream output;
    std::streambuf* oldIn;
    std::streambuf* oldOut;
    Streams(const std::string& text) : input{text}, oldIn{std::cin.rdbuf(input.rdbuf())}, oldOut{std::cout.rdbuf(output.rdbuf())} { std::cin.clear(); }
    ~Streams() { std::cin.rdbuf(oldIn); std::cout.rdbuf(oldOut); std::cin.clear(); }
};
int main()
{
    int failures{};
    auto check = [&](bool ok, const char* message) { if (!ok) { std::cerr << message << '\n'; ++failures; } };
    { Streams io{"x\n0\n101\n999999999999999999999999999999\n43x\n100 tail\ny leftover\nn more\n"};
      check(getGuess(3, 1, 100) == 43, "Recover invalid text, bounds, and overflow; accept numeric prefix");
      check(io.output.str() == std::string{"Guess #3: Guess #3: Guess #3: Guess #3: Guess #3: "}, "Retries must retain guess number");
      check(getGuess(4, 1, 100) == 100, "Discard prior trailing text; include upper endpoint");
      check(playAgain(), "Accept y and discard its trailing text");
      check(!playAgain(), "Next response must be n, not leftover characters"); }
    { Streams io{"1"}; check(getGuess(1, 1, 100) == 1, "Accept lower endpoint without final newline"); check(getGuess(2, 1, 100) == -1, "Stop at EOF after accepted final token"); }
    { Streams io{"5\n9"}; check(getGuess(2, 5, 9) == 5, "Honor custom lower bound"); check(getGuess(3, 5, 9) == 9, "Honor custom upper bound"); }
    { Streams io{"x"}; check(getGuess(1, 1, 100) == -1, "Malformed final token must terminate"); }
    { Streams io{"101"}; check(getGuess(1, 1, 100) == -1, "Out-of-range final token must terminate"); }
    { Streams io{""}; check(getGuess(1, 1, 100) == -1, "Empty guess input"); check(!playAgain(), "Empty replay input"); }
    { Streams io{"2\n"}; check(getGuess(1, 3, 2) == -1 && getGuess(1, 0, 2) == -1, "Invalid bounds return sentinel"); check(io.input.peek() == '2', "Invalid bounds must not consume input"); }
    { Streams io{"q leftovers\nY\nyes\nnonsense\n"}; check(playAgain(), "Retry invalid replay responses; accept lowercase prefix"); check(!playAgain(), "Accept n prefix"); }
    { Streams io{"y"}; check(playAgain(), "Accept final y without newline"); }
    { Streams io{"n"}; check(!playAgain(), "Accept final n without newline"); }
    { Streams io{"q"}; check(!playAgain(), "Invalid replay at EOF terminates"); }
    { Streams io{"42\n"}; std::cin.setstate(std::ios::badbit); check(getGuess(1, 1, 100) == -1, "Bad stream terminates guess read"); check(!playAgain(), "Bad stream terminates replay read"); }
    return failures == 0 ? 0 : 1;
}

