#include <iostream>
#include <limits>
#include <random>

int getGuess(int count, int low, int high)
{
    if (low < 1 || low > high) return -1;
    while (true)
    {
        std::cout << "Guess #" << count << ": ";
        int value{};
        const bool extracted{static_cast<bool>(std::cin >> value)};
        if (std::cin.bad()) return -1;
        if (!extracted && std::cin.eof()) return -1;
        if (!extracted) std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
        if (extracted && value >= low && value <= high) return value;
        if (std::cin.eof() || std::cin.bad()) return -1;
    }
}

bool playAgain()
{
    while (true)
    {
        std::cout << "Replay (y/n): ";
        char response{};
        if (!(std::cin >> response)) return false;
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
        if (response == 'y') return true;
        if (response == 'n') return false;
        if (std::cin.eof() || std::cin.bad()) return false;
    }
}

int playHiLo(int number, int guesses, int low, int high)
{
    std::cout << "Round: " << low << ".." << high << "; tries " << guesses << '\n';
    for (int count{1}; count <= guesses; ++count)
    {
        const int guess{getGuess(count, low, high)};
        if (guess == -1) return -1;
        if (guess > number) std::cout << "Too high\n";
        else if (guess < number) std::cout << "Too low\n";
        else
        {
            std::cout << "You win\n";
            return 1;
        }
    }
    std::cout << "You lose; target " << number << '\n';
    return 0;
}

// Supplied test seam: a pointer to a function taking bounds and returning a target.
using TargetSupplier = int (*)(int, int);

int randomTarget(int low, int high)
{
    static std::mt19937 engine{std::random_device{}()};
    std::uniform_int_distribution<int> target{low, high};
    return target(engine);
}

// Supplied wiring: production uses randomness; tests can substitute a function.
TargetSupplier sessionTarget{randomTarget};

int runSession(TargetSupplier nextTarget)
{
    do
    {
        const int number{nextTarget(1, 100)};
        if (playHiLo(number, 7, 1, 100) == -1) break;
    } while (playAgain());
    std::cout << "Thanks for playing\n";
    return 0;
}

int main()
{
    return runSession(sessionTarget); // Supplied: use the same session in production and tests.
}

