#define main learner_main
#include "main.cpp"
#undef main
#include <sstream>
#include <string>

struct Streams
{
    std::istringstream input;
    std::ostringstream output;
    std::streambuf* oldIn;
    std::streambuf* oldOut;
    Streams(const std::string& text) : input{text}, oldIn{std::cin.rdbuf(input.rdbuf())}, oldOut{std::cout.rdbuf(output.rdbuf())} { std::cin.clear(); }
    ~Streams() { std::cin.rdbuf(oldIn); std::cout.rdbuf(oldOut); std::cin.clear(); }
};
// Independent deterministic supplier: the two rounds deliberately get different targets.
int suppliedCalls{};
bool suppliedBoundsOK{true};
int fakeTarget(int low, int high)
{
    suppliedBoundsOK = suppliedBoundsOK && low == 1 && high == 100;
    ++suppliedCalls;
    return suppliedCalls == 1 ? 100 : 1;
}

int occurrences(const std::string& text, const std::string& needle)
{
    int count{};
    for (auto pos{text.find(needle)}; pos != std::string::npos; pos = text.find(needle, pos + needle.size())) ++count;
    return count;
}

int main()
{
    int failures{};
    auto check = [&](bool ok, const char* message) { if (!ok) { std::cerr << message << '\n'; ++failures; } };
    { Streams io{"x\n0\n101\n60extra\n20\n42suffix\nn trailing\n"};
      check(playHiLo(42, 3, 1, 100) == 1, "Invalid lines must not spend attempts; third valid guess wins");
      check(io.output.str() == "Round: 1..100; tries 3\nGuess #1: Guess #1: Guess #1: Guess #1: Too high\nGuess #2: Too low\nGuess #3: You win\n", "Check retry numbering and ordered high/low/win feedback");
      check(!playAgain(), "Replay must begin on a fresh line"); }
    { Streams io{"1\n2\n3\n4\n5\n6\n7\n100\n"};
      check(playHiLo(100, 7, 1, 100) == 0, "Lose after exactly seven wrong guesses");
      check(io.output.str().find("Guess #7: Too low\nYou lose; target 100\n") != std::string::npos, "Reveal target after last failed attempt");
      check(io.output.str().find("Guess #8:") == std::string::npos, "No eighth attempt");
      check(getGuess(1, 1, 100) == 100, "Loss must leave eighth input unread"); }
    { Streams io{"100\n"}; check(playHiLo(100, 1, 1, 100) == 1, "Upper endpoint can win on final allowed guess"); }
    { Streams io{"1"}; check(playHiLo(1, 7, 1, 100) == 1, "Lower endpoint can win immediately without final newline"); check(io.output.str().find("Guess #2:") == std::string::npos, "No guesses after a win"); }
    { Streams io{"5\n9\n"}; check(playHiLo(9, 2, 5, 9) == 1, "Honor configurable bounds and attempt count"); }
    { Streams io{""}; check(playHiLo(42, 7, 1, 100) == -1, "EOF before first guess"); check(io.output.str().find("You lose") == std::string::npos, "EOF is not a loss"); }
    { Streams io{"1\nx"}; check(playHiLo(42, 7, 1, 100) == -1, "EOF after a wrong guess and malformed final input"); check(io.output.str().find("You lose") == std::string::npos, "Do not misreport interrupted rounds"); }
    // Check the supplied RNG adapter's bounds behavior, not any particular draw.
    check(sessionTarget == randomTarget, "Production wiring must initially select the supplied random adapter");
    check(randomTarget(1, 1) == 1 && randomTarget(100, 100) == 100, "Random adapter honors inclusive singleton bounds");
    for (int i{}; i < 32; ++i)
    {
        const int value{randomTarget(1, 100)};
        check(value >= 1 && value <= 100, "Random adapter remains in requested range");
    }
    // Exercise both the API directly and main's actual wiring with a fake supplier.
    for (int throughMain{}; throughMain < 2; ++throughMain)
    {
        suppliedCalls = 0;
        suppliedBoundsOK = true;
        Streams io{"0\n101\n2\n2\n2\n2\n2\n2\n100 suffix\ny extra\n0\n101\n2\n2\n2\n2\n2\n2\n1 suffix\nn extra\n"};
        const TargetSupplier saved{sessionTarget};
        sessionTarget = fakeTarget;
        const int status{throughMain ? learner_main() : runSession(fakeTarget)};
        sessionTarget = saved;
        check(status == 0, "Session exits successfully");
        check(suppliedCalls == 2, "Request exactly one fresh target per round, not once per session or per guess");
        check(suppliedBoundsOK, "Every round requests target bounds 1..100");
        const std::string round{"Round: 1..100; tries 7\n"};
        const std::string first{round + "Guess #1: Guess #1: Guess #1: Too low\nGuess #2: Too low\nGuess #3: Too low\nGuess #4: Too low\nGuess #5: Too low\nGuess #6: Too low\nGuess #7: You win\nReplay (y/n): "};
        const std::string second{round + "Guess #1: Guess #1: Guess #1: Too high\nGuess #2: Too high\nGuess #3: Too high\nGuess #4: Too high\nGuess #5: Too high\nGuess #6: Too high\nGuess #7: You win\nReplay (y/n): Thanks for playing\n"};
        check(io.output.str() == first + second, "Both rounds use their supplied target, bounds, seven attempts, cleanup, and replay");
        check(occurrences(io.output.str(), "You win\n") == 2, "Both controlled targets must actually reach the game");
    }
    { Streams io{""}; suppliedCalls = 0; suppliedBoundsOK = true;
      const TargetSupplier saved{sessionTarget}; sessionTarget = fakeTarget;
      check(learner_main() == 0, "Session EOF exits normally"); sessionTarget = saved;
      check(suppliedCalls == 1 && suppliedBoundsOK, "Interrupted first round requests just its one bounded target");
      check(io.output.str().find("Replay (y/n):") == std::string::npos, "Do not ask to replay an interrupted round");
      check(io.output.str().ends_with("Thanks for playing\n"), "EOF session farewell"); }
    return failures == 0 ? 0 : 1;
}
